// Turns shared/_locales/*/messages.json into the one file the website and the
// phone can actually read.
//
// Chrome reads `_locales` itself: the extension's copy is a verbatim copy, made
// by sync-shared.mjs like every other generated file. The other two surfaces
// have no such machinery, and neither can simply fetch the JSON:
//
//   - the phone's shell is loaded with `loadFileURL` on iOS, and a `file://`
//     page is its own opaque origin — `fetch` and XHR both refuse it. Android
//     serves the same folder over https and would have been fine, which is
//     exactly the kind of difference that produces a feature working on one
//     phone and not the other.
//   - the website could fetch it, but not before the first paint. A page whose
//     translations arrive a round-trip late is a page that flashes English at a
//     French reader on every load — the same flash shared/theme.js exists to
//     avoid, and the same answer: a blocking <script> in <head>.
//
// So both take a script instead of a document. `description` is dropped on the
// way through: it is a note to translators, it is a third of the bytes, and
// nothing at run time has ever read one.
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');

/** The locales this ships, in the order shared/i18n.js offers them. */
export const LANGS = ['en', 'fr'];

export const localePath = (lang) =>
  join(root, 'shared', '_locales', lang, 'messages.json');

/** `{ en: { key: sentence }, fr: … }` — the shape shared/i18n.js reads. */
export function catalogue(read = (lang) => readFileSync(localePath(lang), 'utf8')) {
  return Object.fromEntries(LANGS.map((lang) => [
    lang,
    Object.fromEntries(Object.entries(JSON.parse(read(lang)))
      .map(([key, entry]) => [key, entry.message])),
  ]));
}

/**
 * Every generated copy, as `{ path, content }`.
 *
 * One line per key, sorted the way the source file is not — a diff on a
 * generated file is only worth reading if a changed sentence is one changed
 * line, and JSON.stringify of the whole object would be one line for
 * everything.
 */
export function generated(messages = catalogue()) {
  const body = LANGS.map((lang) => {
    const entries = Object.entries(messages[lang])
      .map(([key, text]) => `    ${JSON.stringify(key)}: ${JSON.stringify(text)},`);
    return `  ${JSON.stringify(lang)}: {\n${entries.join('\n')}\n  },`;
  }).join('\n');
  const content = `// Generated by scripts/build-messages.mjs from shared/_locales/.\n`
    + `// Edit the locale files, not this one — \`npm run sync:shared\` rewrites it.\n`
    + `globalThis.PanelFlowMessages = {\n${body}\n};\n`;
  return [
    { path: join(root, 'web', 'messages.js'), content },
    { path: join(root, 'mobile', 'www', 'messages.js'), content },
  ];
}
